      '【何を聞かれているか】夏のすずしい気候を利用して高原でレタスやキャベツなどの野菜を時期をずらして栽培する方法である。\n\n【なぜそうなるのか】標高が高い土地は気温が低く（およそ100mで0.6℃下がる）、暑さに弱いレタスやキャベツを平地の産地が出荷できない夏の時期に出荷でき、ほかの産地が出せない時期に出すため高い値段で売れる。\n\n【ステップ1】抑制栽培（高冷地農業）は標高1000mの高原が同じ地域の平地より6℃ほどすずしいことを利用し、夏でも作れる。長野県の野辺山原（八ヶ岳のふもと）、群馬県の嬬恋村（浅間山のふもと）で行われている。\n\n【ステップ2】高原は大消費地から遠いので保冷トラックで新鮮なうちに運び、高速道路の整備が産地の発展を支えた。対になる促成栽培（あたたかい宮崎・高知で出荷を早める）と抑制栽培（すずしい長野・群馬で出荷を遅らせる）はどちらも「ほかが出せない時期に出す」という同じねらいで、促は早める、抑はおさえるという漢字の意味で区別する。\n\n【答え】抑制栽培（高冷地農業）\n\n【確かめ】促成栽培（早める）と抑制栽培（遅らせる）を漢字の意味から区別できるようにする。\n\n【よくあるまちがい】抑制栽培と促成栽培を混同する。抑制栽培はすずしい高原で出荷を遅らせ、促成栽培はあたたかい平野で出荷を早める。\n\n【ここが絶対】「抑制栽培（高原・出荷を遅らせる）と促成栽培（暖地・出荷を早める）」の対比は地理の最頻出事項。',
