      '【何を聞かれているか】海につくった「いけす」やいかだなどで魚や貝・海そうを人の手で育てて出荷する漁業である。\n\n【なぜそうなるのか】1970年代以降各国が200海里の水域を設けて遠洋漁業ができなくなり、さらにとりすぎで近海の資源も減ったため、とる量が自然まかせでは経営が安定せず計画的に育てて出荷できる養殖が重んじられるようになった。\n\n【ステップ1】養殖業（養殖漁業）はいけす・いかだ・池などで魚・貝・海そうを卵や稚魚から出荷できる大きさまで人の手で育てる漁業。主な産地はかき（広島湾・松島湾）、真珠（三重県の英虞湾・長崎県）、ほたて（陸奥湾・オホーツク海沿岸）、のり（有明海・瀬戸内海）、うなぎ（浜名湖・鹿児島）、ぶり・まだい（愛媛・大分）で、いずれも波がおだやかで栄養分の多い内湾という共通点がある。\n\n【ステップ2】課題はえさの食べ残しやふんで海底が汚れること、せまい所に多くの魚を入れると病気が広がりやすいこと、えさに天然の小魚を使うため結局は資源を使っているという指摘もある。栽培漁業（途中で海に放す）とは、出荷まで育てるか途中で放すかという点でちがう。\n\n【答え】養殖漁業（養殖業）\n\n【確かめ】「とる漁業」から「育てる漁業」への転換という位置づけを確認する。\n\n【よくあるまちがい】養殖業と栽培漁業を混同する。養殖業は出荷まで育て、栽培漁業は途中で放流して自然の中で育てる。\n\n【ここが絶対】「養殖業（出荷まで育てる）と栽培漁業（途中で放流）」の区別は地理の最頻出事項。',
