      '【何を聞かれているか】一つの事件について3回まで裁判を受けられるようにしているしくみである。\n\n【なぜそうなるのか】裁判をするのは人であり判断をまちがえることがあるため、まちがった判決で人の自由や財産が失われるのを防ぐため慎重さを確保するしくみとして設けられている。\n\n【ステップ1】三審制は第一審（簡易裁判所・家庭裁判所・地方裁判所）、第二審（地方裁判所・高等裁判所）、第三審（高等裁判所・最高裁判所）の順で審理される。控訴は第一審の判決に不服で第二審へ訴えること、上告は第二審の判決に不服で第三審へ訴えることで、「控訴」が先「上告」が後（上に行くほど「上」告）と覚える。\n\n【ステップ2】えん罪を防ぐほかの仕組みは推定無罪の原則、黙秘権、弁護人を依頼する権利、自白だけでは有罪にできない決まり、令状がなければ逮捕されない原則。判決が確定した後でも新しい証拠が見つかれば裁判をやり直す再審の制度もあり、実際に無罪となった例がある。\n\n【答え】三審制\n\n【確かめ】控訴（第一審→第二審）と上告（第二審→第三審）の順番を確認する。\n\n【よくあるまちがい】控訴と上告を逆に使う。第一審への不服申し立てが控訴、第二審への不服申し立てが上告である。\n\n【ここが絶対】「三審制（控訴→上告）」は公民の最頻出事項。',
