    difficulty: 'advanced',
    question: '江戸時代に全国を測量して歩き、正確な日本地図をつくった人物はだれですか。',
    answer: '伊能忠敬',
    hint: '日本各地を歩いて測量しました。',
    explanation:
      '【何を聞かれているか】江戸時代に全国を測量して歩き正確な日本地図をつくった人物である。\n\n【なぜそうなるのか】地球の大きさを知りたいという個人の探究心と、外国船が近づくなか正確な海岸線の地図を必要としていた幕府の事情が重なって実現した事業だった。\n\n【ステップ1】伊能忠敬は55歳から日本全国を歩いて測量し正確な日本地図『大日本沿海輿地全図』のもとをつくった（完成は死後の1821年）。歩幅を一定にして歩数を数える歩測を基本に間縄や測量器具を使い夜には星の位置を観測して緯度を確かめ、17年をかけ歩いた距離はおよそ4万km（地球一周分に近い）。\n\n【ステップ2】海岸線の形は現在の地図と重ねてもほとんどずれがなく、日本に来たシーボルトがこの地図を持ち出そうとして事件になったほど価値の高いものだった。同じころの人物は杉田玄白・前野良沢（解体新書）、本居宣長（国学・古事記伝）、間宮林蔵（樺太が島であることを確認）。\n\n【答え】伊能忠敬\n\n【確かめ】伊能忠敬の測量距離（およそ4万km）が地球一周分に近いことを確認する。\n\n【よくあるまちがい】伊能忠敬を杉田玄白や間宮林蔵と混同する。伊能忠敬は日本地図をつくった人物である。\n\n【ここが絶対】「伊能忠敬＝日本地図『大日本沿海輿地全図』」は歴史の最頻出事項。',
    examFrequency: 'medium',
