      '【答え】ユニセフ（UNICEF・国連児童基金）\n\n【何をする組織か】世界の子どもたちの命と健康を守り、教育を受けられるように支援する国連の機関である。もともとは第二次世界大戦で被害を受けた子どもを助けるためにつくられ、日本も戦後に脱脂粉乳などの支援を受けた。いま支援する側にいる日本も、かつては支援を受ける側だった。\n\n【主な活動】\n・予防接種、栄養不良の子どもへの治療食\n・安全な水と衛生設備（トイレ）の整備\n・学校の建設、教材の提供\n・紛争や災害のときの緊急支援\n・児童労働・児童婚をなくす活動\n\n【なぜ子どもなのか】子どもは自分で環境を選べず、紛争や貧困の影響を最も強く受ける。栄養や教育が足りないと、その影響は一生続き、次の世代にも引きつがれる。いま手を打つことが、将来の貧困を断ち切ることにつながる。\n\n【子どもの権利条約】1989年に国連で採択された。生きる権利・育つ権利・守られる権利・参加する権利の4つを定めている。日本は1994年に批准した。\n\n【ほかの国連機関】世界保健機関（保健）、国連難民高等弁務官事務所（難民）、国連教育科学文化機関（教育・文化）。',
