    explanation:
      '【答え】大仙古墳（大山古墳・仁徳天皇陵古墳）\n\n【どれくらい大きいか】大阪府堺市にあり、全長およそ486m、周囲に三重の濠をめぐらせている。日本最大の前方後円墳で、規模だけでいえばエジプトのピラミッドや中国の始皇帝陵と並ぶ世界有数の墓である。2019年に「百舌鳥・古市古墳群」として世界遺産に登録された。\n\n【なぜ大きな古墳をつくったのか】ここが要点である。これだけのものをつくるには、莫大な人手と、それを動かす力が必要になる。つまり古墳の大きさは、そこに葬られた人の力の大きさを表している。しかも見上げるような大きさの墓を残すことで、その力を後の世にも示すことができた。\n\n【前方後円墳とは】円形と方形（四角）を組み合わせた形で、上から見ると鍵あなのように見える。日本独特の形である。\n\n【古墳の分布から分かること】前方後円墳は近畿地方を中心に、東北南部から九州まで広く分布している。同じ形の墓が各地にあることから、大和政権の勢力がその範囲に及んでいたと考えられている。墓の形が、支配の広がりを教えてくれる。\n\n【埴輪】古墳の上やまわりに並べられた素焼きの土製品。',
